dleplugin.phpinstall:
$configFile = ENGINE_DIR . '/data/honeypot_config.json';
if (!file_exists($configFile)) {
    $defaultConfig = [
        'mode'              => 'hybrid',
        'tarpit_seconds'    => 15,
        'log_enabled'       => true,
        'log_max_lines'     => 2000,
        'vectors'           => [
            'wp_login'         => true,
            'wp_admin'         => true,
            'wp_xmlrpc'        => true,
            'wp_rest_users'    => true,
            'sensitive_files'  => true,
            'spider_trap'      => true,
            'webshell_catcher' => true,
            'dle_admin'        => false,
        ],
        'autoban_enabled'   => true,
        'autoban_threshold' => 3,
        'autoban_days'      => 0,
        'feed_enabled'      => true,
        'feed_token'        => 'hp_' . bin2hex(random_bytes(12)),
        'feed_format'       => 'plain',
        'abuseipdb_enabled' => false,
        'abuseipdb_key'     => '',
        'ai_trap_enabled'      => true,
        'ai_trap_mode'         => 'combined',
        'ai_trap_scope_decoys' => true,
        'ai_trap_scope_public' => false,
        'ai_trap_custom_text'  => '',
    ];
    @file_put_contents($configFile, json_encode($defaultConfig, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE), LOCK_EX);
}

// Auto-sync core module files from repository if missing or outdated
$targetCore = ENGINE_DIR . '/modules/honeypot.php';
$targetInc  = ENGINE_DIR . '/inc/honeypot.php';
$rawBase = 'https://raw.githubusercontent.com/shlyahten/dle-wordpress-honeypot/main/upload';

if (function_exists('http_get_contents')) {
    if (!file_exists($targetCore) || strpos((string)@file_get_contents($targetCore), 'injectSpiderTrap') === false) {
        $newCore = @http_get_contents($rawBase . '/engine/modules/honeypot.php');
        if ($newCore && strpos($newCore, 'injectSpiderTrap') !== false) {
            @file_put_contents($targetCore, $newCore, LOCK_EX);
        }
    }
    if (!file_exists($targetInc) || strpos((string)@file_get_contents($targetInc), 'save_vectors') === false) {
        $newInc = @http_get_contents($rawBase . '/engine/inc/honeypot.php');
        if ($newInc && strpos($newInc, 'save_vectors') !== false) {
            @file_put_contents($targetInc, $newInc, LOCK_EX);
        }
    }
}

// Ensure honeypot icon exists
$iconFile = ROOT_DIR . '/public/adminpanel/images/honeypot.png';
if (!file_exists($iconFile) && file_exists(ROOT_DIR . '/public/adminpanel/images/iptools.png')) {
    @copy(ROOT_DIR . '/public/adminpanel/images/iptools.png', $iconFile);
}

// Auto-create quarantine directory with strict security
$quarantineDir = ENGINE_DIR . '/data/quarantine';
if (!is_dir($quarantineDir)) {
    @mkdir($quarantineDir, 0750, true);
    $htaccess = "Order Deny,Allow\nDeny from all\nOptions -ExecCGI -Indexes\nRemoveHandler .php .phtml .php3 .php4 .php5 .php7 .phps .cgi .pl .py .asp .jsp .sh\n";
    @file_put_contents($quarantineDir . '/.htaccess', $htaccess, LOCK_EX);
    @file_put_contents($quarantineDir . '/index.html', '', LOCK_EX);
}

// Auto-create decoy endpoints in root if permissions allow
$wpAdminDir = ROOT_DIR . '/wp-admin';
if (!is_dir($wpAdminDir)) {
    @mkdir($wpAdminDir, 0755, true);
}

$decoyFiles = [
    ROOT_DIR . '/wp-login.php' => "<?php\n/* WordPress Login Decoy */\nrequire_once __DIR__ . '/engine/modules/honeypot.php';\nSiteHoneypot::handle('wp-login');\n",
    ROOT_DIR . '/wp-admin/index.php' => "<?php\n/* WordPress Admin Decoy Index */\nrequire_once __DIR__ . '/../engine/modules/honeypot.php';\nSiteHoneypot::handle('wp-admin');\n",
    ROOT_DIR . '/wp-admin/admin.php' => "<?php\n/* WordPress Admin Decoy Handler */\nrequire_once __DIR__ . '/../engine/modules/honeypot.php';\nSiteHoneypot::handle('wp-admin');\n",
    ROOT_DIR . '/xmlrpc.php' => "<?php\n/* WordPress XML-RPC Decoy */\nrequire_once __DIR__ . '/engine/modules/honeypot.php';\nSiteHoneypot::handle('xmlrpc');\n",
];

foreach ($decoyFiles as $path => $code) {
    if (!file_exists($path)) {
        @file_put_contents($path, $code, LOCK_EX);
    }
}

dleplugin.phpupgrade:
// Auto-sync updated core files on upgrade
$targetCore = ENGINE_DIR . '/modules/honeypot.php';
$targetInc  = ENGINE_DIR . '/inc/honeypot.php';
$rawBase = 'https://raw.githubusercontent.com/shlyahten/dle-wordpress-honeypot/main/upload';

$fetchFile = function($url) {
    if (function_exists('http_get_contents')) {
        $data = @http_get_contents($url);
        if ($data && strlen($data) > 100) return $data;
    }
    if (function_exists('curl_init')) {
        $ch = curl_init($url);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($ch, CURLOPT_FOLLOWLOCATION, true);
        curl_setopt($ch, CURLOPT_TIMEOUT, 10);
        curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false);
        curl_setopt($ch, CURLOPT_USERAGENT, 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) DLE-Honeypot-Updater');
        $res = curl_exec($ch);
        curl_close($ch);
        if ($res && strlen($res) > 100) return $res;
    }
    return @file_get_contents($url);
};

$newCore = $fetchFile($rawBase . '/engine/modules/honeypot.php');
if ($newCore && strpos($newCore, 'SiteHoneypot') !== false) {
    @file_put_contents($targetCore, $newCore, LOCK_EX);
}

$newInc = $fetchFile($rawBase . '/engine/inc/honeypot.php');
if ($newInc && strpos($newInc, 'tab-analytics') !== false) {
    @file_put_contents($targetInc, $newInc, LOCK_EX);
}

// Auto-create quarantine directory if missing
$quarantineDir = ENGINE_DIR . '/data/quarantine';
if (!is_dir($quarantineDir)) {
    @mkdir($quarantineDir, 0750, true);
    $htaccess = "Order Deny,Allow\nDeny from all\nOptions -ExecCGI -Indexes\nRemoveHandler .php .phtml .php3 .php4 .php5 .php7 .phps .cgi .pl .py .asp .jsp .sh\n";
    @file_put_contents($quarantineDir . '/.htaccess', $htaccess, LOCK_EX);
    @file_put_contents($quarantineDir . '/index.html', '', LOCK_EX);
}

// Migrate v1.5.0 Anti-AI configuration defaults if missing
$configFile = ENGINE_DIR . '/data/honeypot_config.json';
if (file_exists($configFile)) {
    $cfg = @json_decode(file_get_contents($configFile), true);
    if (is_array($cfg) && !isset($cfg['ai_trap_enabled'])) {
        $cfg['ai_trap_enabled']      = true;
        $cfg['ai_trap_mode']         = 'combined';
        $cfg['ai_trap_scope_decoys'] = true;
        $cfg['ai_trap_scope_public'] = false;
        $cfg['ai_trap_custom_text']  = '';
        @file_put_contents($configFile, json_encode($cfg, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE), LOCK_EX);
    }
}

